112	    machine('Order', {
113	      state: { status: field(t.named('Status'), ($) => $.Draft), items: field(t.range(0, 3), () => 0) },
114	      items: [
115	        action('Place', {}),
116	        action('Pay', { amount: t.int.check([10, 20]) }),
117	        on('Place', ($) => [require($.status === $.Draft, 'not-draft'), require($.items > 0, 'empty-order'), set('status', $.Placed)]),
118	        on('Pay', ($) => [require($.status === $.Placed, 'not-placed'), emit('charge', { amount: $.amount })]),
119	        effect('charge', { amount: t.int }, [labels(['egress:external']), cls('irreversible')]),
