  const typeDecl = (name) => module.decls.find((d) => (d.kind === 'EnumDecl' || d.kind === 'TypeDecl') && d.name === name);
  const instances = map.instances ?? {};
  const methods = map.methods ?? {};
  const queries = map.queries ?? {};

