import { test } from 'node:test';
import assert from 'node:assert/strict';
import createHost from '../build/host.gen.ts';

const deliverTo = async (h: any, to: string, action: string) => {
  const m = (await h.inFlight()).find((x: any) => x.to === to && x.action === action);
  assert.ok(m, `no ${action} to ${to}`);
  await h.deliver(m.id);
};

test('initial state', async () => {
  const h = await createHost();
  assert.deepEqual(await h.run(), { status: 'idle', task0: 'idle', task1: 'idle', retried0: false, retried1: false });
  assert.deepEqual(await h.worker('worker0'), { status: 'idle' });
  assert.equal(await h.worker('nope'), null);
  assert.equal((await h.workDone('worker0')).ok, false);
  assert.equal((await h.cancel()).ok, false);
  assert.equal((await h.workDone('nope')).ok, false);
});

test('start sends Assign and completes', async () => {
  const h = await createHost();
  assert.deepEqual(await h.start(), { ok: true });
  assert.equal((await h.start()).ok, false);
  assert.deepEqual(await h.run(), { status: 'running', task0: 'assigned', task1: 'assigned', retried0: false, retried1: false });
  const msgs = await h.inFlight();
  assert.deepEqual(msgs.map((m: any) => [m.from, m.to, m.action, m.data]).sort(),
    [['run', 'worker0', 'Assign', {}], ['run', 'worker1', 'Assign', {}]]);
  await h.deliverAll();
  assert.deepEqual(await h.worker('worker1'), { status: 'busy' });
  assert.deepEqual(await h.workDone('worker0'), { ok: true });
  const r = await h.inFlight();
  assert.deepEqual(r.map((m: any) => [m.from, m.to, m.action, m.data]), [['worker0', 'run', 'Report', { task: 0, outcome: 'completed' }]]);
  await h.deliverAll();
  assert.deepEqual(await h.run(), { status: 'running', task0: 'completed', task1: 'assigned', retried0: false, retried1: false });
  await h.workDone('worker1');
  await h.deliverAll();
  assert.deepEqual(await h.run(), { status: 'completed', task0: 'completed', task1: 'completed', retried0: false, retried1: false });
});

test('failure', async () => {
  const h = await createHost();
  await h.start(); await h.deliverAll();
  await h.workFailed('worker1'); await h.deliverAll();
  assert.deepEqual(await h.run(), { status: 'running', task0: 'assigned', task1: 'assigned', retried0: false, retried1: true });
  assert.deepEqual(await h.worker('worker1'), { status: 'busy' });
  await h.workDone('worker0'); await h.deliverAll();
  await h.workFailed('worker1'); await h.deliverAll();
  assert.deepEqual(await h.run(), { status: 'failed', task0: 'completed', task1: 'failed', retried0: false, retried1: true });
});

