import { test } from 'node:test';
import assert from 'node:assert/strict';
import createHost from '../build/host.gen.ts';

const deliverTo = async (h: any, to: string, action: string) => {
  const m = (await h.inFlight()).find((x: any) => x.to === to && x.action === action);
  assert.ok(m, `no ${action} to ${to}`);
  await h.deliver(m.id);
};
const view = (status: string, task0: string, task1: string, extra: object = {}) =>
  ({ status, task0, task1, retried0: false, retried1: false, processed: 0, ...extra });
const wire = (msgs: any[]) => msgs.map((m: any) => [m.from, m.to, m.action, m.data]).sort();

test('initial state', async () => {
  const h = await createHost();
  assert.deepEqual(await h.run(), view('idle', 'idle', 'idle'));
  assert.deepEqual(await h.worker('worker0'), { status: 'idle' });
  assert.equal(await h.worker('nope'), null);
  assert.equal((await h.workDone('worker0', 1)).ok, false);
  assert.equal((await h.cancel()).ok, false);
  assert.equal((await h.workDone('nope', 1)).ok, false);
});

test('start sends Assign and completes, counting items', async () => {
  const h = await createHost();
  assert.deepEqual(await h.start(), { ok: true });
  assert.equal((await h.start()).ok, false);
  assert.deepEqual(await h.run(), view('running', 'assigned', 'assigned'));
  assert.deepEqual(wire(await h.inFlight()), [['run', 'worker0', 'Assign', {}], ['run', 'worker1', 'Assign', {}]]);
  await h.deliverAll();
  assert.deepEqual(await h.worker('worker1'), { status: 'busy' });
  assert.equal((await h.workDone('worker0', 0)).ok, false);
  assert.equal((await h.workDone('worker0', 3)).ok, false);
  assert.deepEqual(await h.worker('worker0'), { status: 'busy' });
  assert.deepEqual(await h.workDone('worker0', 2), { ok: true });
  assert.deepEqual(wire(await h.inFlight()), [['worker0', 'run', 'Report', { task: 0, outcome: 'completed', items: 2 }]]);
  await h.deliverAll();
  assert.deepEqual(await h.run(), view('running', 'completed', 'assigned', { processed: 2 }));
  await h.workDone('worker1', 1);
  await h.deliverAll();
  assert.deepEqual(await h.run(), view('completed', 'completed', 'completed', { processed: 3 }));
});

test('failure, retry and second failure', async () => {
  const h = await createHost();
  await h.start(); await h.deliverAll();
  await h.workFailed('worker1');
  assert.deepEqual(wire(await h.inFlight()), [['worker1', 'run', 'Report', { task: 1, outcome: 'failed', items: 0 }]]);
  await h.deliverAll();
